import http from 'k6/http';

export const options = {
  vus: 1,
  iterations: 1,
};

const baseUrl = (__ENV.BASE_URL || '').replace(/\/+$/, '');

function assertSuccess(res, step) {
  if (!res || res.status < 200 || res.status >= 300) {
    throw new Error(`${step} failed with status ${res ? res.status : 'no response'}`);
  }
}

export default function () {
  // Login; k6's per-VU cookie handling stores the session cookie
  // set by this response and sends it on all later requests.
  const loginRes = http.post(
    `${baseUrl}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: { 'Content-Type': 'application/json' } }
  );
  assertSuccess(loginRes, 'login');

  let csrf = null;
  try {
    csrf = loginRes.json('csrf');
  } catch (e) {
    csrf = null;
  }
  if (!csrf) {
    try {
      csrf = JSON.parse(loginRes.body).csrf;
    } catch (e) {
      csrf = null;
    }
  }
  if (!csrf) {
    throw new Error('csrf token not found in login response');
  }

  const productsRes = http.get(`${baseUrl}/products`);
  assertSuccess(productsRes, 'products');

  const cartRes = http.post(
    `${baseUrl}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );
  assertSuccess(cartRes, 'cart');

  const checkoutRes = http.post(
    `${baseUrl}/checkout`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );
  assertSuccess(checkoutRes, 'checkout');
}
