    JSON.stringify({ username: 'bench', password: 'bench' }),
    {
      headers: {
        'Content-Type': 'application/json',
      },
    }
  );

  if (!check(loginRes, { 'login status is 200': (r) => r.status === 200 })) {
    throw new Error(`Login failed with status ${loginRes.status}`);
  }

  const csrf = loginRes.json('csrf');
  if (!csrf) {
    throw new Error('Missing csrf token in login response');
  }

  const productsRes = http.get(`${baseUrl}/products`);
  if (!check(productsRes, { 'products status is 200': (r) => r.status === 200 })) {
    throw new Error(`GET /products failed with status ${productsRes.status}`);
  }

  const cartRes = http.post(
    `${baseUrl}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );

  if (!check(cartRes, { 'cart status is 200': (r) => r.status === 200 })) {
    throw new Error(`POST /cart failed with status ${cartRes.status}`);
  }

  const checkoutRes = http.post(
    `${baseUrl}/checkout`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
